// fakeStore is a Store whose methods call the matching *Fn field when set
// and otherwise return zero values (store.ErrNotFound for lookups). It is
// shared by every test file in this package: set only the hooks you need,
// and do not edit this file (it is owned by the orchestrator).
type fakeStore struct {
	mu sync.Mutex

	GetPublishedPageBySlugFn     func(ctx context.Context, slug string) (model.StatusPage, error)
	ListPublishedCustomDomainsFn func(ctx context.Context) ([]model.PageDomain, error)
	StatusPageUptimeFn           func(ctx context.Context, monitorIDs []int64, fromDay, todayStart time.Time) (map[int64][]model.UptimeDay, error)
	ListIncidentsFn              func(ctx context.Context, pageID int64, includeDrafts bool, limit int) ([]model.Incident, error)
	CreateSubscriberFn           func(ctx context.Context, sub model.Subscriber) (model.Subscriber, bool, error)
	GetSubscriberFn              func(ctx context.Context, id int64) (model.Subscriber, error)
	ConfirmSubscriberFn          func(ctx context.Context, id int64) error
	DeleteSubscriberFn           func(ctx context.Context, pageID, id int64) error
	EnqueueConfirmFn             func(ctx context.Context, subscriberID int64) error
	CountConfirmDeliveriesFn     func(ctx context.Context, since time.Time, pageID int64) (int, error)
	AutoDraftCandidatesFn        func(ctx context.Context, startedBefore time.Time) ([]model.DraftCandidate, error)
	CreateIncidentFn             func(ctx context.Context, in model.Incident, firstBody string) (model.Incident, error)
	ResolveAutoIncidentsFn       func(ctx context.Context, body string) (int, error)
	ClaimDeliveriesFn            func(ctx context.Context, now time.Time, limit int, lease time.Duration) ([]model.Delivery, error)
	MarkDeliverySentFn           func(ctx context.Context, id int64) error
	MarkDeliveryFailedFn         func(ctx context.Context, id int64, errMsg string, maxAttempts int, retryAfter time.Duration) error
	DeferDeliveryFn              func(ctx context.Context, id int64, errMsg string, retryAfter time.Duration) error
	ExpireDeliveriesFn           func(ctx context.Context, before time.Time) (int64, error)
	GetSMTPSettingsFn            func(ctx context.Context) (*model.SMTPSettings, error)
}

func (f *fakeStore) GetPublishedPageBySlug(ctx context.Context, slug string) (model.StatusPage, error) {
	if f.GetPublishedPageBySlugFn != nil {
		return f.GetPublishedPageBySlugFn(ctx, slug)
	}
	return model.StatusPage{}, store.ErrNotFound
}

