// fakeStates is a States over a fixed map.
type fakeStates map[int64]model.MonitorState

func (f fakeStates) State(id int64) (model.MonitorState, bool) {
	st, ok := f[id]
	return st, ok
}

// testNow is the fixed clock of newTestService.
var testNow = time.Date(2026, 10, 10, 12, 0, 0, 0, time.UTC)

// newTestService builds a Service over st with a fixed clock (testNow),
// BaseURL "https://upsera.test", secret "test-secret-test-secret-test-sec!"
// and a discarding logger. mut may adjust the options before New.
func newTestService(t *testing.T, st Store, states States, mut func(*Options)) *Service {
	t.Helper()
	opts := Options{
		Store: st, States: states, Secret: []byte("test-secret-test-secret-test-sec!"),
		BaseURL: "https://upsera.test", Now: func() time.Time { return testNow },
		Logger: slog.New(slog.NewTextHandler(io.Discard, nil)),
	}
	if mut != nil {
		mut(&opts)
	}
	return New(opts)
}
